package com.tanerinal.education.web;import com.tanerinal.education.service.*;import com.tanerinal.education.web.dto.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api")@PreAuthorize("hasRole('CUSTOMER')")public class ReceiptReviewController{private final CurrentUserService users;private final ReceiptReviewService service;public ReceiptReviewController(CurrentUserService users,ReceiptReviewService service){this.users=users;this.service=service;}@PostMapping("/purchase-orders/{id}/receive")ShopOrderResponse receive(@PathVariable Long id,Authentication a){return service.receive(users.require(a),id);}@PostMapping("/order-items/{id}/reviews")ProductReviewResponse review(@PathVariable Long id,@Valid@RequestBody ReviewRequest request,Authentication a){return service.review(users.require(a),id,request);}}
